// Hand-written. Not generated by Speakeasy.
package provider

import (
	"context"
	"testing"

	"github.com/hashicorp/terraform-plugin-framework/provider"
)

// TestProviderHasClusterConsistencyValidator guards the validator's existence.
// Without it a mismatched server_url and api_server_id create a service on one
// cluster and look for it on another, so apply succeeds and the next refresh
// fails with a 403 -- leaving a service Terraform can neither read nor delete.
func TestProviderHasClusterConsistencyValidator(t *testing.T) {
	p, ok := New("test")().(provider.ProviderWithConfigValidators)
	if !ok {
		t.Fatal("provider no longer implements ProviderWithConfigValidators; " +
			"see internal/provider/config_validation.go")
	}
	if len(p.ConfigValidators(context.Background())) == 0 {
		t.Fatal("provider has no config validators registered")
	}
}

// TestClusterConsistencyOnlyFiresForKnownHosts is the important half: an
// unrecognised host must never be flagged, because Dedicated Cloud, On-Premise
// and pre-production deployments legitimately set an api_server_id the provider
// cannot verify.
func TestClusterConsistencyOnlyFiresForKnownHosts(t *testing.T) {
	for _, host := range []string{
		"https://nextdev-api.authlete.net",
		"https://authlete.customer.example.com",
	} {
		if _, known := APIServerIDForServerURL(host); known {
			t.Errorf("%s is treated as a known cluster; the validator would "+
				"second-guess an operator-supplied api_server_id", host)
		}
	}
	for host, want := range map[string]int64{
		"https://us.authlete.com": 76281,
		"https://jp.authlete.com": 53285,
	} {
		got, known := APIServerIDForServerURL(host)
		if !known || got != want {
			t.Errorf("APIServerIDForServerURL(%q) = (%d, %v), want (%d, true)", host, got, known, want)
		}
	}
}
